state = loop_state or {}
pool = state.get("pool") or []
# Correctness-floor gate (structural, not prompt-deep): a hypothesis that a
# reviewer scored unsound (correctness < 5) or that was never reviewed cannot
# hold the headline slot, no matter how many debates its ambition won. This
# fixes the observed failure where the Elo tournament crowned a correctness-4,
# novelty-9 hypothesis. Elo still orders within each tier — we only demote
# unsound/unreviewed candidates BELOW sound ones, we do not distort the Elo.
CORRECTNESS_FLOOR = 5.0
def _corr_val(h):
    rv = h.get("reviews") or {}
    corr = rv.get("correctness")
    if isinstance(corr, bool):
        return None
    if isinstance(corr, int) or isinstance(corr, float):
        return float(corr)
    return None
def _unsafe(h):
    # Only a reviewed, explicit False counts as unsafe (unreviewed/None is not).
    rv = h.get("reviews") or {}
    return bool(h.get("reviewed")) and (rv.get("safety_ok") is False)
def _sort_key(h):
    corr_v = _corr_val(h)
    reviewed = bool(h.get("reviewed")) and corr_v is not None
    # tier 0 = reviewed, safe, sound; 1 = reviewed, safe, unsound;
    # 2 = unreviewed; 3 = reviewed but flagged UNSAFE (never headline).
    if _unsafe(h):
        tier = 3
    elif not reviewed:
        tier = 2
    elif corr_v < CORRECTNESS_FLOOR:
        tier = 1
    else:
        tier = 0
    return (tier, -float(h.get("elo", 0)))
ranked = sorted(pool, key=_sort_key)
out = []
for rank, h in enumerate(ranked, 1):
    corr_v = _corr_val(h)
    flags = []
    if _unsafe(h):
        flags.append("unsafe")
    if not bool(h.get("reviewed")):
        flags.append("unreviewed")
    elif corr_v is not None and corr_v < CORRECTNESS_FLOOR:
        flags.append("low_correctness")
    out.append({
        "rank": rank,
        "elo": int(float(h.get("elo", 0))),
        "reviewed": bool(h.get("reviewed")),
        "flags": flags,
        "title": h.get("title"),
        "statement": h.get("statement"),
        "rationale": h.get("rationale"),
        "experiment": h.get("experiment"),
        "reviews": h.get("reviews") or {},
    })
warnings = list(state.get("warnings") or [])
unreviewed = 0
unsafe = 0
for h in out:
    if not h.get("reviewed"):
        unreviewed = unreviewed + 1
    if "unsafe" in (h.get("flags") or []):
        unsafe = unsafe + 1
if unreviewed > 0:
    warnings.append("#FALLBACK: " + str(unreviewed) + " finalist(s) reached the ranking without a completed review; flagged 'unreviewed' and demoted below reviewed hypotheses.")
if unsafe > 0:
    warnings.append("#FALLBACK: " + str(unsafe) + " hypothesis(es) were flagged unsafe by the reviewer; flagged 'unsafe' and demoted below all safe hypotheses — do not action without human safety review.")
return {
    "ranked_hypotheses": out,
    "top": out[0] if out else {},
    "cycles": int(state.get("cycle", 0) or 0),
    "pool_size": len(out),
    "sources": state.get("sources") or [],
    "literature": str(state.get("literature") or ""),
    "grounding_ok": bool(state.get("grounding_ok")),
    "warnings": warnings,
}

goal = str(research_goal or "").strip()
ranked = (final or {}).get("ranked_hypotheses") or []
lit = str((final or {}).get("literature") or "").strip()
top = ranked[:5]
parts = ["You are the Meta-review agent. Synthesize the top-ranked hypotheses below into a rigorous research overview for a scientist: the most promising directions and WHY they rank highly (reference their reviews), how they relate to the current literature, the key open questions, and concrete suggested next experiments. START YOUR RESPONSE with exactly these two elements before anything else: FIRST LINE 'TITLE: <a concise professional report title you derive from the FINDINGS themselves, 5-12 words, headline style — NEVER the verbatim research goal, never a question>'; SECOND (after a blank line) 'ABSTRACT: <one paragraph of 4-6 sentences summarizing the hypothesis landscape, the strongest directions, and the key insight — a real scientific abstract>'. Then continue with the overview. FORMAT: write flowing PROSE in GitHub-flavored Markdown with section headings (##) — this is a human-readable research overview, NOT a data dump. Do NOT return JSON, do NOT wrap the answer in a code block. REQUIRED VISUAL ELEMENTS (the exported report renders GitHub pipe tables and fenced code blocks; mermaid/HTML/images do NOT render — never emit them): (1) exactly one comparison TABLE of the key hypotheses as a GitHub pipe table, comparing DESIGN dimensions a scientist decides by — core mechanism, what it improves over the literature, main risk or failure mode, and the evidence an experiment must produce (do NOT tabulate Elo/review scores; those are already tabulated elsewhere in the report; additional tables for OTHER content, e.g. experiment matrices, are welcome); and (2) at least one SCHEMA/FIGURE as a fenced ASCII diagram (open the fence with three backticks on the word text) sketching the architecture of the top hypothesis or how the key hypotheses relate — boxes and arrows drawn with characters like +--+, |, ->. Keep every table cell one line. CRITICAL HONESTY RULE: these hypotheses are UNTESTED proposals. Never write that they 'report', 'demonstrate', 'achieve', or 'show' any result — no experiment was run. Present every quantitative figure as a hypothesized/expected TARGET to be tested, and do not assert benchmark results as if observed. If a hypothesis is flagged 'unreviewed' or 'low_correctness', say so rather than promoting it.", "", "## Research goal", goal]
if lit:
    parts += ["", "## Literature base", lit[:2500]]
parts += ["", "## Top ranked hypotheses (with Elo + reviews)"]
for h in top:
    parts.append("### #" + str(h.get("rank")) + " " + str(h.get("title")) + " (Elo " + str(h.get("elo")) + ")")
    parts.append(str(h.get("statement") or ""))
    if h.get("experiment"):
        parts.append("Experiment: " + str(h.get("experiment")))
    rv = h.get("reviews") or {}
    fl = h.get("flags") or []
    if fl:
        parts.append("FLAGS: " + ", ".join(fl) + " (do not present a flagged hypothesis as a top recommendation without saying so).")
    if rv.get("critique"):
        parts.append("Reviewer note (corr=" + str(rv.get("correctness")) + ", nov=" + str(rv.get("novelty")) + ", safety_ok=" + str(rv.get("safety_ok")) + "): " + str(rv.get("critique"))[:300])
    parts.append("")
return "\n".join(parts)

